-- DoorSphere expanded category catalogue: healthy meals, fresh produce, Ayurveda and online services.
-- Catalogue visibility does not enable ordering or consultations.
on conflict (slug) do update set
  name = excluded.name,
  vertical = excluded.vertical,
  description = excluded.description,
  regulated = excluded.regulated,
  launch_wave = excluded.launch_wave,
  catalogue_visible = true;
